const calculateGrade = (maxStr, gotStr) => {
  const max2 = parseFloat(maxStr);
  const got = parseFloat(gotStr);
  if (isNaN(max2) || isNaN(got) || max2 <= 0 || got < 0) {
    return ["—", "—"];
  }
  const pct = got / max2 * 100;
  const grade = pct >= 90 ? "A+" : pct >= 75 ? "A" : pct >= 60 ? "B" : pct >= 45 ? "C" : pct >= 33 ? "D" : "E";
  const pass = pct >= 33 ? "उत्तीर्ण ✅" : "अनुत्तीर्ण ❌";
  return [grade, pass];
};
